def busiest_rooms(visits: list[tuple[str, str]], top: int) -> list[str]:
    rooms: list[str] = []
    counts: list[int] = []
    for _visitor, room in visits:
        if room in rooms:
            counts[rooms.index(room)] += 1
        else:
            rooms.append(room)
            counts.append(1)
    ranked = sorted(zip(counts, rooms), reverse=True)
    return [room for _count, room in ranked[:top]]

