import sqlite3


def rent_canoe(connection: sqlite3.Connection, canoe_id: int, slot: str, customer: str) -> bool:
    row = connection.execute(
        "SELECT customer FROM rentals WHERE canoe_id = ? AND slot = ?", (canoe_id, slot)
    ).fetchone()
    if row is not None:
        return False
    connection.execute(
        "INSERT INTO rentals (canoe_id, slot, customer) VALUES (?, ?, ?)", (canoe_id, slot, customer)
    )
    connection.commit()
    return True

