_CELLS = {chr(ord("a") + i): chr(0x2801 + i) for i in range(26)} | {" ": "\u2800"}
_LETTERS = {cell: letter for letter, cell in _CELLS.items()}


def encode(text: str) -> str:
    return "".join(_CELLS[c] for c in text.lower())


def decode(cells: str) -> str:
    return "".join(_LETTERS[c] for c in cells)

